npx tsx _audit_shell/check_teststudent_data.ts 2>&1 | head -3; echo ---; npx tsx -e "
import { createClient } from '@supabase/supabase-js';
import { readFileSync } from 'node:fs';
const raw = readFileSync('.env.local','utf8');
for (const line of raw.split('\n')) { const t=line.trim(); if(!t||t.startsWith('#'))continue; const eq=t.indexOf('='); if(eq===-1)continue; const k=t.slice(0,eq).trim(); let v=t.slice(eq+1).trim(); if((v.startsWith('\"')&&v.endsWith('\"'))||(v.startsWith(\"'\")&&v.endsWith(\"'\"))) v=v.slice(1,-1); if(!process.env[k]) process.env[k]=v; }
const admin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, {auth:{autoRefreshToken:false,persistSession:false}});
admin.from('profiles').select('email,role,branch,department').in('email',['teststudent@gmail.com','teststudent2@gmail.com','teststudent3@gmail.com','admin@edunexus.com','unnati.shukla@ppsu.ac.in']).then(({data,error})=>console.log(JSON.stringify(data,null,2), error));
"
